package career.assistant.config;
import org.springframework.beans.factory.annotation.Value; import org.springframework.boot.autoconfigure.condition.ConditionalOnMissingBean; import org.springframework.context.annotation.*; import org.springframework.mail.javamail.*; import java.util.Properties;
@Configuration public class MailConfiguration {@Bean @ConditionalOnMissingBean(JavaMailSender.class) JavaMailSender javaMailSender(@Value("${spring.mail.host:smtp.gmail.com}")String host,@Value("${spring.mail.port:587}")int port,@Value("${spring.mail.username:}")String username,@Value("${spring.mail.password:}")String password){JavaMailSenderImpl sender=new JavaMailSenderImpl();sender.setHost(host);sender.setPort(port);sender.setUsername(username);sender.setPassword(password);Properties p=sender.getJavaMailProperties();p.put("mail.smtp.auth","true");p.put("mail.smtp.starttls.enable","true");return sender;}}
